t(1,"filing","20-F","Annual filing by foreign issuers in the US.")
t(1,"setter","IASB","Standard setter that writes IFRS.")
t(1,"setter","FASB","Standard setter that writes US GAAP.")
t(1,"setter","SEC","US regulator that enforces the rules, carries out Sarbanes-Oxley and oversees the PCAOB.")
t(1,"setter","Sarbanes-Oxley (2002)","Created the PCAOB to oversee auditors and requires management to report on the effectiveness of internal control over financial reporting.")
t(1,"setter","PCAOB","Oversees auditors; created by Sarbanes-Oxley.")
