t(1,"opinion","Disclaimer of opinion","The auditor cannot express an opinion (for example, a scope limitation).")
t(1,"opinion","Modified opinion","Any audit opinion other than unqualified.")
# Module 2
t(2,"rev","Revenue recognition five steps","1) Identify the contract, 2) identify the separate performance obligations, 3) determine the transaction price, 4) allocate the price to the obligations, 5) recognize revenue when (or as) each obligation is satisfied.")
