t(2,"principal","Principal (revenue reporting)","Controls the goods and reports revenue gross.")
t(2,"principal","Agent (revenue reporting)","Reports only its commission, net (consignment, marketplace).")
t(2,"rev","Contract costs","Incremental costs of obtaining a contract are capitalized under the converged standard.")
t(2,"rev","Expense recognition","Expenses are recognized when the economic benefits are consumed or lost (matching).")
t(2,"nonrec","Discontinued operations","A component disposed of or classified as held for sale. Shown separately, below continuing operations, net of tax.")
