t(2,"oci","Comprehensive income","Net income + OCI.")
t(2,"oci","OCI items","Foreign currency translation adjustments, unrealized gains and losses on FVOCI (AFS) debt securities, pension remeasurements, effective cash flow hedges, IFRS revaluation surplus.")
# Module 3
t(3,"current","Current assets","Expected to be used up or converted to cash within one year or one operating cycle.")
t(3,"current","Current liabilities","Due within one year or one operating cycle.")
t(3,"ifrsfa","Amortized cost (IFRS financial assets)","Hold to collect principal and interest.")
t(3,"ifrsfa","FVOCI (IFRS financial assets)","Hold to collect and sell; also an irrevocable choice for equity securities.")
t(3,"ifrsfa","FVPL (IFRS financial assets)","Everything else; any asset can be designated at this measure.")
