t(4,"class","Interest paid (classification)","US GAAP: operating. IFRS: operating or financing.")
t(4,"class","Dividends paid (classification)","US GAAP: financing. IFRS: operating or financing.")
t(4,"class","Taxes paid (classification)","US GAAP: operating, always. IFRS: operating, unless specifically tied to an investing or financing transaction.")
t(4,"class","Bank overdraft (classification)","US GAAP: financing. IFRS: can be part of cash and equivalents.")
