t(6,"invmeas","Agricultural and commodity inventories","Both IFRS and US GAAP allow them at NRV or fair value less costs to sell.")
t(6,"rising","LIFO under rising prices","Highest COGS and turnover; lowest margin, net income, ending inventory, current ratio and taxes; highest debt-to-assets.")
t(6,"rising","FIFO under rising prices","Lowest COGS and turnover; highest margin, net income, ending inventory, current ratio and taxes; longest days of inventory.")
t(6,"rising","Weighted average under rising prices","Sits in the middle on COGS, margins, inventory, turnover and taxes.")
t(6,"rising","Inventory closest to current values","FIFO inventory is closest to current value on the balance sheet; LIFO COGS is closest to current cost on the income statement.")
