# Module 9
t(9,"taxbasic","Taxable income","Income on the tax return.")
t(9,"taxbasic","Pretax income","Income on the financial statements.")
t(9,"taxbasic","Taxes payable","The liability from the tax return.")
t(9,"taxbasic","Income tax expense","The P&L charge = taxes payable + change in deferred taxes.")
t(9,"base","Carrying amount","Book value on the financial statements.")
t(9,"base","Tax base","Value the tax authority recognizes.")
t(9,"diff","Temporary difference","Reverses over time and creates deferred tax.")
