t(9,"rate","Cash tax rate","Taxes paid / pretax income.")
# Module 10
t(10,"quality","Financial reporting quality","How well the statements follow GAAP and give decision-useful information.")
t(10,"quality","Earnings quality","Whether reported earnings are sustainable and adequate (high enough to give investors a sufficient return).")
t(10,"quality","Reporting quality spectrum","Six levels from GAAP compliant and decision useful with sustainable, adequate earnings (best) to not compliant and fictitious or fraudulent (worst).")
t(10,"cons","Conservative accounting","Choices that decrease current reported earnings and financial position and may increase them later.")
t(10,"cons","Aggressive accounting","Choices that increase current earnings or financial position and may decrease them later.")
