F = []  # (module, group, name, formula)
def f(m, g, name, formula): F.append((m, g, name, formula))
f(2,"eps","Basic EPS","(net income − preferred dividends) / WASO")
f(2,"eps","Diluted EPS","(NI − preferred dividends + preferred dividends on convertible preferred + after-tax interest on convertible debt) / (WASO + shares from conversion + net shares from options)")
f(2,"eps","After-tax interest on convertible debt","face × coupon × (1 − t)")
f(2,"eps","Treasury stock method net shares","options − (options × exercise price / average market price)")
f(2,"rev","Revenue to date (input method)","(cumulative costs / current total estimated costs) × contract price")
f(2,"rev","This period's long-term contract revenue","revenue to date − revenue already recognized")
f(3,"equity","Ending retained earnings","beginning RE + net income − dividends declared")
f(3,"equity","Goodwill","purchase price − fair value of identifiable net assets")
f(3,"liq","Current ratio","current assets / current liabilities")
f(3,"liq","Quick ratio","(cash + short-term marketable investments + receivables) / current liabilities")
f(3,"liq","Cash ratio","(cash + short-term marketable investments) / current liabilities")
f(3,"solv","Debt-to-assets","total debt / total assets")
f(3,"solv","Debt-to-equity","total debt / total equity")
f(3,"solv","Financial leverage","total assets / total equity")
f(4,"cash","Cash collected from customers","revenue − increase in accounts receivable (+ increase in unearned revenue)")
f(4,"cash","Purchases","COGS + ending inventory − beginning inventory")
f(4,"cash","Cash paid to suppliers","purchases − increase in accounts payable")
f(4,"cash","Cash paid to employees","salary expense − increase in salaries payable")
f(4,"cash","CFO (indirect)","net income + non-cash charges − gains + losses − increase in operating current assets + increase in operating current liabilities")
f(5,"fcf","FCFF (from net income)","NI + non-cash charges + interest × (1 − t) − fixed capital investment − working capital investment")
f(5,"fcf","FCFF (from CFO)","CFO + interest paid × (1 − t) − fixed capital investment")
f(5,"fcf","FCFE (from CFO)","CFO − fixed capital investment + net borrowing")
f(5,"fcf","FCFE (from FCFF)","FCFF − interest × (1 − t) + net borrowing")
f(5,"cfr","Cash flow to revenue","CFO / revenue")
f(5,"cfr","Cash return on assets","CFO / average total assets")
f(5,"cfr","Cash return on equity","CFO / average equity")
f(5,"cfr","Cash to income","CFO / operating income")
f(5,"cfr","Cash flow per share","(CFO − preferred dividends) / WASO")
f(5,"cfc","Debt coverage (cash flow)","CFO / total debt")
f(5,"cfc","Interest coverage (cash flow)","(CFO + interest paid + taxes paid) / interest paid")
f(5,"cfc","Reinvestment ratio","CFO / cash paid for long-term assets")
f(5,"cfc","Debt payment ratio","CFO / cash paid for long-term debt repayment")
f(5,"cfc","Dividend payment ratio","CFO / dividends paid")
f(5,"cfc","Investing and financing ratio","CFO / cash outflows for investing and financing")
f(6,"lifo","FIFO inventory","LIFO inventory + LIFO reserve")
f(6,"lifo","FIFO COGS","LIFO COGS − (ending LIFO reserve − beginning LIFO reserve)")
f(6,"lifo","LIFO to FIFO: equity adjustment","add LIFO reserve × (1 − t) to equity")
f(6,"lifo","LIFO to FIFO: deferred tax adjustment","add LIFO reserve × t to deferred tax liabilities (or taxes payable)")
f(7,"imp","IFRS impairment loss","carrying amount − max(fair value − costs to sell, value in use)")
f(7,"imp","US GAAP impairment loss (if recoverability test fails)","carrying amount − fair value")
f(7,"age","Average age of PP&E","accumulated depreciation / annual depreciation expense")
f(7,"age","Total useful life of PP&E","gross PP&E / annual depreciation expense")
f(7,"age","Remaining useful life of PP&E","net PP&E / annual depreciation expense")
f(9,"tax","Income tax expense","taxes payable + ΔDTL − ΔDTA")
f(9,"tax","Deferred tax (DTL or DTA)","(carrying amount − tax base) × tax rate (positive for an asset means DTL)")
f(9,"tax","Effective tax rate","income tax expense / pretax income")
f(11,"act","Receivables turnover","revenue / average receivables")
f(11,"act","Days of sales outstanding (DSO)","365 / receivables turnover")
f(11,"act","Inventory turnover","COGS / average inventory")
f(11,"act","Days of inventory on hand (DOH)","365 / inventory turnover")
f(11,"act","Payables turnover","purchases / average payables")
f(11,"act","Days of payables","365 / payables turnover")
f(11,"act","Working capital turnover","revenue / average working capital")
f(11,"act","Fixed asset turnover","revenue / average net fixed assets")
f(11,"act","Total asset turnover","revenue / average total assets")
f(11,"act","Cash conversion cycle","DOH + DSO − days of payables")
f(11,"liq11","Defensive interval","(cash + short-term investments + receivables) / daily cash expenditures")
f(11,"solv11","Debt-to-capital","total debt / (total debt + equity)")
f(11,"solv11","Interest coverage","EBIT / interest")
f(11,"solv11","Fixed charge coverage","(EBIT + lease payments) / (interest + lease payments)")
f(11,"prof","Gross, operating, pretax and net margin","each profit line / revenue")
f(11,"prof","ROA","net income / average total assets")
f(11,"prof","ROE","net income / average total equity")
f(11,"prof","Return on total capital","EBIT / (debt + equity)")
f(11,"dup","3-part DuPont","ROE = net profit margin × total asset turnover × financial leverage")
f(11,"dup","ROE from ROA","ROE = ROA × financial leverage")
f(11,"dup","5-part DuPont","ROE = tax burden (NI/EBT) × interest burden (EBT/EBIT) × EBIT margin (EBIT/revenue) × asset turnover × leverage")
f(11,"grow","Retention rate (b)","1 − dividend payout ratio")
f(11,"grow","Sustainable growth (g)","b × ROE")
f(12,"m12","Projected line item","projected revenue × historical % of revenue")
f(12,"m12","Pro forma CFO","net income + depreciation − increase in net working capital")

